/* Reproducible screenshots from DRIFT's actual framebuffer, no UI mockups. */
#include "../web/emu/felucca_web.c"
static void tick(void){for(int i=0;i<400;i++)web_render(128);}
static void shot(const char *path){FILE *f=fopen(path,"wb");fprintf(f,"P6\n240 240\n255\n");for(int i=0;i<240*240;i++){uint16_t c=web_fb[i];c=(c>>8)|(c<<8);unsigned char b[3]={(c>>11)*255/31,((c>>5)&63)*255/63,(c&31)*255/31};fwrite(b,1,3,f);}fclose(f);}
int main(void){web_nor_erase();web_boot();tick();drift_load(0);drift_page=D_HOME;tick();shot("build/site-patches.ppm");drift_page=D_ENV;ui.force=1;tick();shot("build/site-envelope.ppm");trk[0].p[P_ROOT]=2;trk[0].p[P_SCALE]=2;drift_page=D_SCL;ui.force=1;tick();shot("build/site-scale.ppm");trk[0].p[P_DPITCH]=7;trk[0].p[P_DOCT]=2;trk[0].p[P_DRHYTHM]=34;trk[0].p[P_DRATE]=18;drift_page=D_SEQ2;ui.force=1;tick();shot("build/site-sequence.ppm");drift_load(0);song.g[G_BPM]=80;drift_page=D_FX;ui.force=1;tick();shot("build/site-delay.ppm");drift_page=D_SPACE;ui.force=1;tick();shot("build/site-reverb.ppm");drift_page=D_TYPES;ui.force=1;tick();shot("build/site-misc.ppm");drift_load(21);drift_page=D_TAPE;ui.force=1;tick();shot("build/site-tape.ppm");name_open(NK_USER_SAVE,0);str_cpy(nm.s,"VELVET TAPE",sizeof nm.s);nm.len=str_len(nm.s);nm.cur=3;ui.force=1;tick();shot("build/site-save.ppm");name_close();drift_load(25);drift_page=D_OSC;ui.force=1;tick();shot("build/site-string.ppm");drift_load(28);drift_page=D_OSC;ui.force=1;tick();shot("build/site-resonator.ppm");drift_load(29);drift_page=D_OSC;ui.force=1;tick();shot("build/site-bowed.ppm");drift_load(30);drift_page=D_OSC;ui.force=1;tick();shot("build/site-air.ppm");return 0;}
